import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../../environments/environment';
import { User } from '../models/user.model';
import { Pro } from '../models/pro.model';

export interface Job {
  id: number;
  userId: number;
  userName?: string;
  title: string;
  categoryId?: number;
  category?: {
    id: number;
    name: string;
  };
  description: string;
  location: string;
  budget: string;
  timeline: string;
  status: string;
  isBid?: boolean;
  assignedProId?: number;
  assignedProBusinessName?: string;
  jobPhases?: string;
  attachments?: string;
  createdAt: string;
  updatedAt?: string;
}

export interface ImpersonationData {
  token: string;
  userId: number;
  userType: string;
}

export interface CommissionConfig {
  userCommissionPercent: number;
  proCommissionPercent: number;
  gstPercent: number;
  minPlatformFee: number;
  maxCommissionPercent: number;
}

export interface RegistrationMetrics {
  users: number;
  pros: number;
  businesses: number;
}

export interface CategoryJobCount {
  categoryId: number | null;
  categoryName: string;
  categoryIcon?: string | null;
  count: number;
}

export interface JobsByCategoryFilter {
  country?: string;
  state?: string;
  district?: string;
  from?: string;
  to?: string;
}

@Injectable({
  providedIn: 'root'
})
export class AdminUsersService {
  private apiUrl = environment.apiUrl;

  constructor(private http: HttpClient) {}

  // Search for users by email or name
  searchUsers(query: string): Observable<any> {
    return this.http.get(`${this.apiUrl}/admin/users/search`, {
      params: { query }
    });
  }

  // Search for pros by email or name
  searchPros(query: string): Observable<any> {
    return this.http.get(`${this.apiUrl}/admin/pros/search`, {
      params: { query }
    });
  }

  // Get user details
  getUserDetails(userId: number): Observable<User> {
    return this.http.get<User>(`${this.apiUrl}/users/${userId}`);
  }

  // Get pro details
  getProDetails(proId: number): Observable<Pro> {
    return this.http.get<Pro>(`${this.apiUrl}/pros/${proId}`);
  }

  // Get user's job history
  getUserJobs(userId: number): Observable<any> {
    return this.http.get<any>(`${this.apiUrl}/jobs/users/${userId}/jobs`);
  }

  // Get pro's job history
  getProJobs(proId: number): Observable<any> {
    return this.http.get<any>(`${this.apiUrl}/jobs/pros/${proId}/jobs`);
  }

  // Get user's messages/conversations
  getUserConversations(userId: number): Observable<any> {
    return this.http.get<any>(`${this.apiUrl}/messages/conversations`, {
      params: { userId: userId.toString(), userType: 'User' }
    });
  }

  // Get pro's messages/conversations
  getProConversations(proId: number): Observable<any> {
    return this.http.get<any>(`${this.apiUrl}/messages/conversations`, {
      params: { userId: proId.toString(), userType: 'Pro' }
    });
  }

  // Get messages for a specific conversation
  getMessages(userId1: number, userType1: string, userId2: number, userType2: string): Observable<any> {
    return this.http.get<any>(`${this.apiUrl}/messages`, {
      params: { 
        userId1: userId1.toString(),
        userType1: userType1,
        userId2: userId2.toString(),
        userType2: userType2
      }
    });
  }

  // Impersonate as a user
  impersonateUser(userId: number, userType: string): Observable<ImpersonationData> {
    return this.http.post<ImpersonationData>(`${this.apiUrl}/admin/impersonate`, {
      targetUserId: userId,
      targetUserType: userType
    });
  }

  // Invite a new admin
  inviteAdmin(email: string): Observable<any> {
    console.log('inviteAdmin service called with email:', email);
    const body = { email: email };
    console.log('Sending request body:', body);
    return this.http.post(`${this.apiUrl}/admin/invite`, body);
  }

  // Get admin invitations
  getAdminInvitations(pendingOnly: boolean = true): Observable<any> {
    return this.http.get(`${this.apiUrl}/admin/invitations`, {
      params: { pendingOnly: pendingOnly.toString() }
    });
  }

  // Resend admin invitation
  resendAdminInvitation(invitationId: number): Observable<any> {
    return this.http.post(`${this.apiUrl}/admin/invitations/${invitationId}/resend`, {});
  }

  createUser(payload: any): Observable<any> {
    return this.http.post(`${this.apiUrl}/users`, payload);
  }

  createPro(payload: any): Observable<any> {
    return this.http.post(`${this.apiUrl}/pros`, payload);
  }

  getPendingGeocodePros(): Observable<any[]> {
    return this.http.get<any[]>(`${this.apiUrl}/admin/pros/geocode-backfill/pending`);
  }

  getPendingGeocodeUsers(): Observable<any[]> {
    return this.http.get<any[]>(`${this.apiUrl}/admin/users/geocode-backfill/pending`);
  }

  geocodeBackfillPros(): Observable<any> {
    return this.http.post(`${this.apiUrl}/admin/pros/geocode-backfill`, {});
  }

  geocodeBackfillUsers(): Observable<any> {
    return this.http.post(`${this.apiUrl}/admin/users/geocode-backfill`, {});
  }

  updateProServiceRadius(proId: number, serviceRadiusKm: number): Observable<any> {
    return this.http.patch(`${this.apiUrl}/admin/pros/${proId}/service-radius`, { serviceRadiusKm });
  }

  getDisputes(): Observable<any[]> {
    return this.http.get<any[]>(`${this.apiUrl}/admin/disputes`);
  }

  // History of resolved disputes, with optional date range (ISO) and free-text search.
  getResolvedDisputes(from?: string, to?: string, search?: string): Observable<any[]> {
    const params: Record<string, string> = {};
    if (from) params['from'] = from;
    if (to) params['to'] = to;
    if (search) params['search'] = search;
    return this.http.get<any[]>(`${this.apiUrl}/admin/disputes/resolved`, { params });
  }

  // Dashboard: counts of users/pros/businesses joined in a time frame (ISO timestamps).
  getRegistrationMetrics(from?: string, to?: string): Observable<RegistrationMetrics> {
    const params: Record<string, string> = {};
    if (from) params['from'] = from;
    if (to) params['to'] = to;
    return this.http.get<RegistrationMetrics>(`${this.apiUrl}/admin/metrics/registrations`, { params });
  }

  // Dashboard: job counts per category for a selected region/date range.
  getJobsByCategory(filter: JobsByCategoryFilter = {}): Observable<CategoryJobCount[]> {
    const params: Record<string, string> = {};
    if (filter.country) params['country'] = filter.country;
    if (filter.state) params['state'] = filter.state;
    if (filter.district) params['district'] = filter.district;
    if (filter.from) params['from'] = filter.from;
    if (filter.to) params['to'] = filter.to;
    return this.http.get<CategoryJobCount[]>(`${this.apiUrl}/admin/metrics/jobs-by-category`, { params });
  }

  getAdminPayments(status?: string, userId?: number, proId?: number): Observable<any[]> {
    const parts: string[] = [];
    if (status)  parts.push(`status=${status}`);
    if (userId)  parts.push(`userId=${userId}`);
    if (proId)   parts.push(`proId=${proId}`);
    const qs = parts.length ? `?${parts.join('&')}` : '';
    return this.http.get<any[]>(`${this.apiUrl}/payments/admin${qs}`);
  }

  refundPayment(paymentId: number, reason: string): Observable<any> {
    return this.http.post(`${this.apiUrl}/payments/${paymentId}/refund`, { reason });
  }

  resolveDispute(jobId: number, resolution: 'complete' | 'refund', notes?: string): Observable<any> {
    return this.http.post(`${this.apiUrl}/admin/jobs/${jobId}/completion/resolve`, { resolution, notes });
  }

  getCommissionConfig(): Observable<CommissionConfig> {
    return this.http.get<CommissionConfig>(`${this.apiUrl}/admin/commission-config`);
  }

  updateCommissionConfig(config: CommissionConfig): Observable<{ message: string }> {
    return this.http.put<{ message: string }>(`${this.apiUrl}/admin/commission-config`, config);
  }
}
